/* ============================================================
   Static map imagery for the demo objects.

   Real OpenStreetMap tiles (zoom 16) fetched once around each object's actual
   coordinates, stitched and cropped so the point sits dead centre of the frame.
   Baked in as data URLs because the stand is one self-contained file that has to
   open from disk with no network: a live tile layer would render a grey box.

   Map data © OpenStreetMap contributors, ODbL. The attribution is rendered under
   every map — do not remove it.
   ============================================================ */
(function (WS) {
  'use strict';
  WS.maps = {
    o_creekline: 'data:image/jpeg;base64,',
    o_palmcourt: 'data:image/jpeg;base64,',
    o_bayline: 'data:image/jpeg;base64,',
  };
})(window.WS = window.WS || {});
